import{_ as a,c as e,o as i,ag as t}from"./chunks/framework.Bgp3UCEi.js";const p=JSON.parse('{"title":"2025.1.5","description":"","frontmatter":{"title":"2025.1.5"},"headers":[],"relativePath":"changelog/latest.md","filePath":"changelog/latest.md","lastUpdated":1767086401000}'),r={name:"changelog/latest.md"};function o(n,l,s,h,u,d){return i(),e("div",null,[...l[0]||(l[0]=[t('<p>我们怀着激动的心情宣布，View Shadcn UI v2025.1.5 版本已于 2025 年 12 月 30 日正式发布！这是一个革命性的版本更新，为组件库带来了令人惊艳的液态玻璃（Glassmorphism）设计美学，让您的应用界面焕然一新。</p><h2 id="📋-版本信息" tabindex="-1">📋 版本信息 <a class="header-anchor" href="#📋-版本信息" aria-label="Permalink to &quot;📋 版本信息&quot;">​</a></h2><ul><li><strong>版本号</strong>: 2025.1.5</li><li><strong>发布日期</strong>: 2025 年 12 月 30 日</li><li><strong>项目地址</strong>: <a href="https://github.com/devlive-community/view-shadcn-ui" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui</a></li><li><strong>官方网站</strong>: <a href="https://view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://view-shadcn-ui.devlive.org/</a></li><li><strong>演练场</strong>: <a href="https://playground.view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://playground.view-shadcn-ui.devlive.org/</a></li></ul><h2 id="✨-核心特性" tabindex="-1">✨ 核心特性 <a class="header-anchor" href="#✨-核心特性" aria-label="Permalink to &quot;✨ 核心特性&quot;">​</a></h2><h4 id="🌊-液态玻璃效果全面覆盖" tabindex="-1">🌊 液态玻璃效果全面覆盖 <a class="header-anchor" href="#🌊-液态玻璃效果全面覆盖" aria-label="Permalink to &quot;🌊 液态玻璃效果全面覆盖&quot;">​</a></h4><p>本次更新的最大亮点是为 40+ 组件添加了精心设计的液态玻璃效果，带来通透、层次分明的现代化视觉体验。</p><p><strong>已支持液态玻璃效果的组件</strong>：</p><p><strong>基础组件</strong></p><ul><li>Alert（警告提示）、Avatar（头像）、Badge（徽章）、Button（按钮）</li><li>Text（文本）、Skeleton（骨架屏）</li></ul><p><strong>表单组件</strong></p><ul><li>Form（表单）、Select（选择器）、Slider（滑块）、Switch（开关）</li><li>Toggle（切换）、DatePicker（日期选择器）、ColorPicker（颜色选择器）</li><li>Upload（上传）</li></ul><p><strong>导航组件</strong></p><ul><li>Menu（菜单）、Breadcrumb（面包屑）、Pagination（分页）</li><li>Tab（标签页）、BackTop（返回顶部）</li></ul><p><strong>反馈组件</strong></p><ul><li>Message（消息）、Modal（模态框）、Drawer（抽屉）</li><li>Tooltip（提示）、Progress（进度条）、Spin（加载）</li></ul><p><strong>数据展示</strong></p><ul><li>Table（表格）、Collapse（折叠面板）、Carousel（轮播）</li></ul><p><strong>高级组件</strong></p><ul><li>ContextMenu（右键菜单）、Dropdown（下拉菜单）</li><li>CountDown（倒计时）、Contribution（贡献图）</li></ul><p><strong>布局组件</strong></p><ul><li>Global Footer（全局页脚）、Toolbar Footer（工具栏页脚）</li></ul><h4 id="🎯-功能增强" tabindex="-1">🎯 功能增强 <a class="header-anchor" href="#🎯-功能增强" aria-label="Permalink to &quot;🎯 功能增强&quot;">​</a></h4><p><strong>选择器组件优化</strong></p><ul><li>✨ 新增搜索功能，支持快速筛选选项</li></ul><p><strong>Markdown 组件</strong></p><ul><li>🆕 全新支持 Markdown 渲染组件</li></ul><h4 id="🐛-问题修复" tabindex="-1">🐛 问题修复 <a class="header-anchor" href="#🐛-问题修复" aria-label="Permalink to &quot;🐛 问题修复&quot;">​</a></h4><ul><li>✅ 修复右键菜单多级菜单下父级隐藏问题</li><li>✅ 修复下拉菜单位置在右侧时列表显示异常</li><li>✅ 修复嵌套菜单异常问题</li><li>✅ 修复菜单宽度不一致问题</li><li>✅ 修复抽屉组件顶部空白问题</li></ul><h4 id="🛠️-工程优化" tabindex="-1">🛠️ 工程优化 <a class="header-anchor" href="#🛠️-工程优化" aria-label="Permalink to &quot;🛠️ 工程优化&quot;">​</a></h4><ul><li>📦 优化 CI/CD 流程，拆分构建脚本</li><li>📚 文档全面适配暗黑模式</li><li>🔧 修复 VitePress 部署配置问题</li></ul><h2 id="💡-关于-view-shadcn-ui" tabindex="-1">💡 关于 View Shadcn UI <a class="header-anchor" href="#💡-关于-view-shadcn-ui" aria-label="Permalink to &quot;💡 关于 View Shadcn UI&quot;">​</a></h2><p>View Shadcn UI 是一个基于 Tailwind CSS 构建的现代化 Vue3 组件库，专注于提供优雅、高性能且易于使用的 UI 组件。我们致力于将最新的设计趋势与最佳的开发实践相结合，帮助开发者构建出色的用户界面。</p><h2 id="🙏-致谢" tabindex="-1">🙏 致谢 <a class="header-anchor" href="#🙏-致谢" aria-label="Permalink to &quot;🙏 致谢&quot;">​</a></h2><p>感谢社区的每一位贡献者和用户！你们的支持和反馈是我们不断前进的动力。</p>',34)])])}const c=a(r,[["render",o]]);export{p as __pageData,c as default};
